package com.basssg.thaidailynews;
import android.app.Activity;import android.appwidget.AppWidgetManager;import android.os.Bundle;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.JSONObject;
public class WidgetPreviewActivity extends Activity {
    private android.appwidget.AppWidgetHost host;
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.parseColor("#080F1C"));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(22),dp(38),dp(22),dp(30));scroll.addView(list);setContentView(scroll);int[] ids=getIntent().getIntArrayExtra("widgetIds");if(ids!=null)host=new android.appwidget.AppWidgetHost(this,220);int index=0;for(String kind:new String[]{"small","medium","large"}){TextView label=new TextView(this);label.setText(kind.equals("small")?"THAI DAILY · 2 × 2":kind.equals("medium")?"THAI DAILY · 4 × 2":"THAI DAILY · 4 × 4");label.setTextColor(Color.parseColor("#D6B775"));label.setTextSize(11);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);lp.bottomMargin=dp(10);list.addView(label,lp);int height=kind.equals("large")?285:kind.equals("small")?146:128;Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,height);View widget=host==null?NewsWidgetProvider.createViews(this,-1,kind,options).apply(this,list):host.createView(this,ids[index],AppWidgetManager.getInstance(this).getAppWidgetInfo(ids[index]));index++;list.addView(widget,new LinearLayout.LayoutParams(kind.equals("small")?dp(165):-1,dp(height)));}}
    @Override protected void onStart(){super.onStart();if(host!=null)host.startListening();}
    @Override protected void onStop(){if(host!=null)host.stopListening();super.onStop();}
}
